package com.dailyhelp.service;
import com.dailyhelp.dto.AuthDtos.*; import com.dailyhelp.entity.AppUser; import com.dailyhelp.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder; public AuthService(UserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;} public UserResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase();if(users.existsByEmail(email))throw new IllegalArgumentException("An account with this email already exists");AppUser u=users.save(new AppUser(r.name().trim(),email,encoder.encode(r.password())));return view(u);} public UserResponse current(String email){return users.findByEmail(email).map(this::view).orElseThrow(()->new java.util.NoSuchElementException());} private UserResponse view(AppUser u){return new UserResponse(u.getId(),u.getName(),u.getEmail(),u.getCreatedAt());}}